INSERT INTO `activity` VALUES (1,1,2,'把黄昏拍成一张明信片','带上相机，一起走过校园的草坪、长廊和最后一束夕阳。零基础也欢迎。','ART','东操场草坪','','2026-10-03 09:00:41.000000','2026-10-03 11:00:41.000000','2026-10-03 08:00:41.000000',24,'PUBLISHED',1,'','2026-09-30 23:01:41.096583','2026-09-30 23:01:41.112616'),(2,2,4,'周末三人篮球，来组队！','轻松友好的校园篮球局。无需固定队伍，现场一起认识新朋友。','SPORT','南区篮球场','','2026-10-04 07:00:41.000000','2026-10-04 09:00:41.000000','2026-10-04 06:00:41.000000',18,'PUBLISHED',1,'','2026-09-30 23:01:41.113833','2026-09-30 23:01:41.114731'),(3,3,2,'把你的奇思妙想做出来','一起做一个小网页、一张海报，或者分享最近的灵感。欢迎带着半成品来。','TECH','创客教室 203','','2026-10-05 11:00:41.000000','2026-10-05 13:00:41.000000','2026-10-05 10:00:41.000000',16,'PUBLISHED',1,'','2026-09-30 23:01:41.114836','2026-09-30 23:01:41.116519'),(4,2,4,'草坪上的校园志愿日','给校园公共空间做一次小整理，用一个下午换一个更舒服的角落。','VOLUNTEER','图书馆前草坪','','2026-10-06 06:00:41.000000','2026-10-06 08:00:41.000000','2026-10-06 05:00:41.000000',30,'PUBLISHED',1,'','2026-09-30 23:01:41.116427','2026-09-30 23:01:41.117451'),(5,1,2,'今天的追光准备会','用于演示器材申请、审批、领取与归还的活动。','ART','社团器材室','','2026-10-01 01:01:41.000000','2026-10-01 03:01:41.000000','2026-10-01 00:01:41.000000',10,'PUBLISHED',1,'','2026-09-30 23:01:41.117427','2026-09-30 23:01:41.118191');
